package dev.aura.player;
import android.content.Context;import android.net.Uri;import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;

/** Uncompressed DSF / DSDIFF decoder. Streaming SoX decimation or standard DoP packaging. */
public final class Dsd {
    public record Header(int channels,int rate,long samples,int block,boolean lsb,long data,long length,boolean dsf) {}
    private static String id(RandomAccessFile f)throws IOException{byte[] b=new byte[4];f.readFully(b);return new String(b,StandardCharsets.US_ASCII);}
    private static long le64(RandomAccessFile f)throws IOException{return Long.reverseBytes(f.readLong());}private static int le32(RandomAccessFile f)throws IOException{return Integer.reverseBytes(f.readInt());}
    public static Header header(RandomAccessFile f)throws IOException{f.seek(0);String magic=id(f);if(magic.equals("DSD ")){if(le64(f)!=28)throw new IOException("잘못된 DSF 헤더");f.seek(28);int ch=0,rate=0,block=0,bits=0;long samples=0;while(f.getFilePointer()+12<=f.length()){long start=f.getFilePointer();String tag=id(f);long size=le64(f);if(size<12||size>f.length()-start)throw new IOException("DSF 청크 크기 오류");if(tag.equals("fmt ")){if(size<52)throw new IOException("DSF fmt 오류");le32(f);if(le32(f)!=0)throw new IOException("지원하지 않는 DSF 압축");le32(f);ch=le32(f);rate=le32(f);bits=le32(f);samples=le64(f);block=le32(f);}if(tag.equals("data")){validate(ch,rate,samples,block);if(bits!=1&&bits!=8)throw new IOException("DSF 비트 순서 오류");return new Header(ch,rate,samples,block,bits==1,start+12,size-12,true);}f.seek(start+size);}}else if(magic.equals("FRM8")){f.readLong();if(!id(f).equals("DSD "))throw new IOException("DSDIFF 형식이 아닙니다");int ch=0,rate=0;boolean raw=false;while(f.getFilePointer()+12<=f.length()){String tag=id(f);long size=f.readLong(),start=f.getFilePointer();if(size<0||size>f.length()-start)throw new IOException("DFF 청크 크기 오류");if(tag.equals("PROP")){if(!id(f).equals("SND "))throw new IOException("잘못된 DFF PROP");long end=start+size;while(f.getFilePointer()+12<=end){String t=id(f);long n=f.readLong(),at=f.getFilePointer();if(n<0||n>end-at)throw new IOException("DFF 속성 오류");if(t.equals("FS  "))rate=f.readInt();if(t.equals("CHNL"))ch=f.readUnsignedShort();if(t.equals("CMPR"))raw=id(f).equals("DSD ");f.seek(at+n+(n&1));}}if(tag.equals("DSD ")){long samples=ch>0?size*8/ch:0;validate(ch,rate,samples,4096);if(!raw)throw new IOException("압축 DST는 지원하지 않습니다");return new Header(ch,rate,samples,4096,false,start,size,false);}f.seek(start+size+(size&1));}}throw new IOException("지원하지 않는 DSD 파일");}
    private static void validate(int ch,int rate,long samples,int block)throws IOException{if(ch<1||ch>2||rate<2822400||rate>22579200||samples<1||block<1||block>1048576)throw new IOException("지원하지 않는 DSD 구성");}
    public static synchronized File prepare(Context c,Uri source,String mode)throws Exception{if(mode.equals("native"))throw new IOException("이 버전은 Native DSD를 지원하지 않습니다. PCM 또는 DoP를 선택해 주세요.");boolean dop=mode.equals("dop");if(dop&&(!AudioSettings.current.mode().equals("usb")||!AudioSettings.current.perfect()))throw new IOException("DoP는 USB 직접 출력 + 비트퍼펙트 모드에서만 사용할 수 있습니다. DAC의 DoP 지원도 확인해 주세요.");String key=Hex.encode(java.security.MessageDigest.getInstance("SHA-256").digest((source+":"+mode+("file".equals(source.getScheme())?":"+new File(source.getPath()).lastModified()+":"+new File(source.getPath()).length():"")).getBytes(StandardCharsets.UTF_8)));File dir=new File(c.getCacheDir(),"dsd");dir.mkdirs();File output=new File(dir,key+".wav");if(output.exists()&&output.length()>44)return output;File input=new File(dir,key+".source"),temp=new File(dir,key+".partial");try{try(InputStream in=c.getContentResolver().openInputStream(source);OutputStream out=new FileOutputStream(input)){if(in==null)throw new IOException("DSD 파일을 열 수 없습니다");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();out.write(b,0,n);}}
        try(RandomAccessFile in=new RandomAccessFile(input,"r");RandomAccessFile out=new RandomAccessFile(temp,"rw")){Header h=header(in);int rate=dop?h.rate()/16:176400,bits=24;long expected=dop?h.samples()/16*h.channels()*3:h.samples()*rate/h.rate()*h.channels()*3;if(expected>0xfffffff0L||dir.getUsableSpace()<expected+8_000_000)throw new IOException("DSD 변환용 저장 공간이 부족하거나 WAV 4 GB 제한을 초과했습니다");out.setLength(0);writeWav(out,rate,h.channels(),bits,0);long sox=dop?0:NativeAudio.createSox(h.rate(),rate,h.channels(),6,50,95);long consumed=0,marker=0;try{in.seek(h.data());byte[][] planar=new byte[h.channels()][h.block()];while(consumed<h.samples()){if(Thread.currentThread().isInterrupted())throw new InterruptedException();int frames=(int)Math.min(h.block(),(h.samples()-consumed+7)/8);if(h.dsf()){for(int ch=0;ch<h.channels();ch++)in.readFully(planar[ch]);}else{for(int f=0;f<frames;f++)for(int ch=0;ch<h.channels();ch++)planar[ch][f]=in.readByte();}
            if(dop){for(int f=0;f+1<frames;f+=2){for(int ch=0;ch<h.channels();ch++){int first=planar[ch][f]&255,second=planar[ch][f+1]&255;if(h.lsb()){first=Integer.reverse(first)>>>24;second=Integer.reverse(second)>>>24;}out.write(second);out.write(first);out.write((marker&1)==0?5:250);}marker++;}}
            else{int samples=(int)Math.min((long)frames*8,h.samples()-consumed);for(int start=0;start<samples;start+=8192){int count=Math.min(8192,samples-start);float[] block=new float[count*h.channels()];for(int f=0;f<count;f++)for(int ch=0;ch<h.channels();ch++){int at=start+f,bit=h.lsb()?at%8:7-at%8;block[f*h.channels()+ch]=((planar[ch][at/8]>>bit)&1)==0?-1f:1f;}writeFloats(out,NativeAudio.resample(sox,block));}}consumed+=frames*8L;}
            if(sox!=0)writeFloats(out,NativeAudio.resample(sox,null));long bytes=out.length()-44;out.seek(0);writeWav(out,rate,h.channels(),bits,bytes);
        }finally{if(sox!=0)NativeAudio.closeSox(sox);}}
        if(!temp.renameTo(output))throw new IOException("DSD 변환 파일 저장 실패");return output;
    }finally{input.delete();temp.delete();}}
    private static void writeFloats(RandomAccessFile out,float[] samples)throws IOException{byte[] bytes=new byte[samples.length*3];for(int i=0;i<samples.length;i++){long v=Math.max(-8388608,Math.min(8388607,Math.round(samples[i]*8388608.)));bytes[i*3]=(byte)v;bytes[i*3+1]=(byte)(v>>8);bytes[i*3+2]=(byte)(v>>16);}out.write(bytes);}
    public static void writeWav(RandomAccessFile out,int rate,int channels,int bits,long size)throws IOException{ByteBuffer b=ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes(StandardCharsets.US_ASCII)).putInt((int)(size+36)).put("WAVEfmt ".getBytes(StandardCharsets.US_ASCII)).putInt(16).putShort((short)1).putShort((short)channels).putInt(rate).putInt(rate*channels*bits/8).putShort((short)(channels*bits/8)).putShort((short)bits).put("data".getBytes(StandardCharsets.US_ASCII)).putInt((int)size);out.write(b.array());}
}
